mapper.select:
SELECT  COUNT(*)::INT                                                       AS "total"
       ,COUNT(*) FILTER (WHERE INS_DAY >= (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::DATE::TIMESTAMP AT TIME ZONE 'Asia/Seoul')::INT AS "today"
  FROM T_COUPLE_HEART
 WHERE 1=1
   AND COUPLE_ID = #{coupleId}
   AND FROM_ID   = #{fromId}

SELECT COUNT(*)
  FROM T_COUPLE_PHOTO
 WHERE 1=1
   AND COUPLE_ID = #{coupleId}

   AND MILESTONE = #{milestone}

mapper.delete:
DELETE FROM T_COUPLE_PHOTO
 WHERE 1=1
   AND ID        = #{id}
   AND COUPLE_ID = #{coupleId}

